import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"使用条款","description":"Clash 使用条款：自备服务器与订阅、合法使用、外部服务、局域网共享、保证、责任限制及 Apple 标准 EULA。","frontmatter":{"title":"使用条款","description":"Clash 使用条款：自备服务器与订阅、合法使用、外部服务、局域网共享、保证、责任限制及 Apple 标准 EULA。","keywords":["Clash使用条款","Clash EULA","iOS代理使用条款","Clash法律条款"],"jsonLd":{"@context":"https://schema.org","@type":"WebPage","name":"Clash 使用条款","description":"使用 Clash 连接自备服务器、订阅和配置时适用的补充条款。","url":"https://clash.md/zh/terms","inLanguage":"zh-CN","about":["Apple 标准 EULA","合法使用","自备代理服务","责任限制"],"publisher":{"@type":"Organization","name":"OmniWide Media Limited","email":"legal@omniwide.media"}}},"headers":[],"relativePath":"zh/terms.md","filePath":"zh/terms.md","lastUpdated":0}`),a={name:`zh/terms.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="使用条款" tabindex="-1">使用条款 <a class="header-anchor" href="#使用条款" aria-label="Permalink to “使用条款”">​</a></h1><p><strong>最后更新：2026 年 7 月 29 日</strong></p><p>本条款是 <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/" target="_blank" rel="noreferrer">Apple 标准最终用户许可协议</a> 的补充，后者负责约束你使用 Clash 的许可。本条款不会取代 Apple 标准 EULA；如两者发生冲突，以标准 EULA 为准。</p><p>Clash 的发行主体及本条款中的“我们”和“开发者”是指 <strong>OmniWide Media Limited</strong>。</p><h2 id="clash-是什么" tabindex="-1">Clash 是什么 <a class="header-anchor" href="#clash-是什么" aria-label="Permalink to “Clash 是什么”">​</a></h2><p>Clash 是基于 Hako 内核、面向 Apple 平台的网络工具。它会按照你提供的配置在设备上转发网络流量。</p><p><strong>Clash 不提供代理服务。</strong> App 不附带服务器、订阅或账户。它连接的内容均来自你的配置，或<a href="/clash.md/zh/privacy">隐私政策</a>中公开说明的功能端点。</p><h2 id="你的责任" tabindex="-1">你的责任 <a class="header-anchor" href="#你的责任" aria-label="Permalink to “你的责任”">​</a></h2><ul><li><strong>合法使用。</strong> 你有责任确保使用 Clash 的方式符合对你适用的法律，以及你所使用服务的条款。</li><li><strong>你的服务。</strong> 服务器、订阅、DNS 服务与规则来源均由你选择。我们不运营或为其背书，也不对其可用性、安全性、内容或数据处理方式负责。</li><li><strong>你的配置。</strong> Clash 会按照你提供的内容保存配置，包括其中的凭据。你有责任保护设备、配置文件、导出的诊断与备份。</li><li><strong>第三方条款。</strong> 你必须遵守适用的第三方条款，包括网络服务商、已配置服务、Apple 与 iCloud 的条款。</li></ul><p>你不得使用 Clash 违法、侵犯他人权利、干扰网络或服务，或进行未获授权的访问。</p><h2 id="局域网共享" tabindex="-1">局域网共享 <a class="header-anchor" href="#局域网共享" aria-label="Permalink to “局域网共享”">​</a></h2><p>如果启用局域网代理共享，Clash 会监听本地网络，并接受提供了你所设置的用户名与密码的连接。请使用高强度密码，并且只在可信网络中启用共享。 VPN 停止时，共享也会停止。</p><h2 id="外部服务" tabindex="-1">外部服务 <a class="header-anchor" href="#外部服务" aria-label="Permalink to “外部服务”">​</a></h2><p>Clash 可以访问你选择的服务与网站。你需要自行承担使用这些外部服务的风险。我们不控制，也不保证其内容、准确性、安全性、可用性或合法性。</p><h2 id="可用性与支持" tabindex="-1">可用性与支持 <a class="header-anchor" href="#可用性与支持" aria-label="Permalink to “可用性与支持”">​</a></h2><p>网络状况、第三方服务、配置错误与平台行为不受我们控制。Clash 可能中断、不可用或出现非预期行为。按照 Apple 标准 EULA 与适用法律，维护与支持由开发者而非 Apple 提供。</p><h2 id="不提供额外保证" tabindex="-1">不提供额外保证 <a class="header-anchor" href="#不提供额外保证" aria-label="Permalink to “不提供额外保证”">​</a></h2><p>在适用法律允许的最大范围内，Clash 按“现状”和“可用状态”提供，除法律不允许排除的保证外，不提供其他保证。本条款不会限制适用消费者法律不允许我们排除的权利或救济。</p><h2 id="责任限制" tabindex="-1">责任限制 <a class="header-anchor" href="#责任限制" aria-label="Permalink to “责任限制”">​</a></h2><p>在适用法律允许的最大范围内，对于使用或无法使用 Clash 所造成的间接、偶发、特殊、后果性或惩罚性损失，包括数据、网络连接或第三方服务访问的损失，我们不承担责任。法律不允许限制责任的情形不受本条影响。</p><h2 id="开源组件" tabindex="-1">开源组件 <a class="header-anchor" href="#开源组件" aria-label="Permalink to “开源组件”">​</a></h2><p>Clash 包含开源软件，每个组件适用各自的许可证。App 内的“致谢”页面列出了这些组件。本条款不会取代或限制任何开源许可证。</p><h2 id="条款变更" tabindex="-1">条款变更 <a class="header-anchor" href="#条款变更" aria-label="Permalink to “条款变更”">​</a></h2><p>当 App 或适用要求发生变化时，我们可能更新本条款。当前版本与更新日期会发布在本网址。变更仅适用于今后的使用，不会移除适用法律已经赋予你的权利。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to “联系方式”">​</a></h2><p>法律问题、索赔或其他保密事项，请发送电子邮件至 <a href="mailto:legal@omniwide.media" target="_blank" rel="noreferrer">legal@omniwide.media</a>，或邮寄至： <strong>OmniWide Media Limited, 128 City Road, London, United Kingdom, EC1V 2NX</strong>。</p><p>非保密支持问题可以提交到 <a href="https://github.com/TokenPLS/Hako-Client/issues" target="_blank" rel="noreferrer">Clash 客户端 Issue</a>。请勿在公开 Issue 中包含凭据或其他敏感信息。</p>`,27)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};